const secondaryState = flow.get('secondary_gate_state') || {};

let statusText = `🚪 *Secondary Gate Status*\n\n`;

statusText += '*Gate Controls:*\n';
statusText += `Relay 1 (Close): ${secondaryState.relay1 || 'UNKNOWN'}\n`;
statusText += `Relay 2 (Open): ${secondaryState.relay2 || 'UNKNOWN'}\n`;
statusText += `Relay 3 (Trigger): ${secondaryState.relay3 || 'UNKNOWN'}\n`;
statusText += `Relay 4 (Stop): ${secondaryState.relay4 || 'UNKNOWN'}\n\n`;

statusText += '*Lights:*\n';
statusText += `Relay 5 (Left Light): ${secondaryState.relay5 || 'UNKNOWN'}\n`;
statusText += `Relay 6 (Right Light): ${secondaryState.relay6 || 'UNKNOWN'}\n`;

if (secondaryState.lastUpdate) {
    const lastUpdate = new Date(secondaryState.lastUpdate).toLocaleString('ro-RO');
    statusText += `\n🕐 Last update: ${lastUpdate}`;
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};
msg.topic = 'send';

return msg;

